async def signal(event):
    # Deadlock watchdog only. Event order, never elapsed speed, decides correctness.
    await asyncio.wait_for(event.wait(), 1.5)


async def barrier():
    event = asyncio.Event()
    asyncio.get_running_loop().call_soon(event.set)
    await event.wait()


async def finish(task, *gates):
    for gate in gates:
        gate.set()
    if not task.done():
        task.cancel()
    await asyncio.gather(task, return_exceptions=True)


class CheckedCase(unittest.IsolatedAsyncioTestCase):
    async def asyncSetUp(self):
        self.before_tasks = set(asyncio.all_tasks())

    async def asyncTearDown(self):
        current = asyncio.current_task()
        leaked = {task for task in asyncio.all_tasks() if task is not current and task not in self.before_tasks and not task.done()}
        for task in leaked:
            task.cancel()
        if leaked:
            await asyncio.wait(leaked, timeout=0.2)
        self.assertEqual(len(leaked), 0, 'operation leaked unfinished background tasks')


class ProbeAwaitable:
    def __init__(self, value, events=None, label='await', error=None):
        self.value, self.events, self.label, self.error = value, events, label, error
        self.awaits = 0

    def __await__(self):
        self.awaits += 1
        if self.events is not None:
            self.events.append(self.label)
        if self.awaits != 1:
            raise AssertionError('awaitable consumed twice')
        if self.error is not None:
            raise self.error
        if False:
            yield
        return self.value


class ProbeEvent(asyncio.Event):
    def __init__(self):
        super().__init__()
        self.waits = self.sets = self.clears = 0

    async def wait(self):
        self.waits += 1
        return await super().wait()

    def set(self):
        self.sets += 1
        return super().set()

    def clear(self):
        self.clears += 1
        return super().clear()


class ProbeTask(asyncio.Task):
    def __init__(self, coro):
        super().__init__(coro)
        self.cancel_calls = 0

    def cancel(self, msg=None):
        self.cancel_calls += 1
        return super().cancel(msg)
